  ('616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$Scheikunde$$, $$VWO$$, $$Zijde verven$$, $$VWO Scheikunde 2018-I$$),
  ('3ed28797-d260-4238-a4f0-f8d86e295662', $$Scheikunde$$, $$VWO$$, $$Fenolproductie$$, $$VWO Scheikunde 2018-I$$),
