insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('f9d2d792-9231-4442-a471-08a5ee32e448', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$schema — HMF en acht afgeleide stoffen (1-7, FDCA); geen CO₂ vrijkomt$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context1.png$$,
   $$Ieder jaar worden grote hoeveelheden PET-frisdrankflessen geproduceerd. Het Nederlandse bedrijf Avantium heeft een proces ontwikkeld om de kunststof PEF als alternatief voor PET te produceren. Bij de productie van PEF wordt biomassa als grondstof gebruikt, terwijl PET wordt geproduceerd uit aardolie. Voor de productie van PEF worden plantaardige monosachariden zoals glucose gebruikt. Glucose wordt in een eerste proces omgezet tot HMF. Uit HMF kunnen verschillende stoffen worden gemaakt die voor de chemische industrie bruikbaar zijn. Schema: HMF (structuurformule HO-CH₂-furaanring-CHO) staat centraal met pijlen naar acht afgeleide stoffen: stof 1 (cyclische ester/lacton: een zevenring met één O-atoom en één C=O in de ring), stof 2 (H₃C-furaanring-CHO), FDCA (HO-C(=O)-furaanring-C(=O)-OH, furaan-2,5-dicarbonzuur), stof 3 (HO-C(=O)-furaanring-CH₂-OH), stof 4 (HO-CH₂-furaanring-CH₂-OH), stof 5 (H₃C-furaanring-CH₃), stof 6 (HO-C(=O)-CH₂-CH₂-CH₂-CH₂-C(=O)-OH, een dicarbonzuur) en stof 7 (HO-CH₂-CH₂-CH₂-CH₂-CH₂-CH₂-OH, een diol). Bij de omzettingen van glucose tot de bovenstaande reactieproducten komt geen koolstofdioxide vrij in de chemische reacties.$$, 'inline'),
  ('571a1c46-4e4b-4c36-8e68-20a6b36c7cec', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$vergisting van glucose tot bio-ethanol; atoomeconomie-vergelijking$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context2.png$$,
   $$Een ander gebruik van glucose is vergisting tot bio-ethanol, een proces dat kan worden weergegeven met onderstaande reactievergelijking. C₆H₁₂O₆ → 2 C₂H₆O + 2 CO₂. De atoomeconomie van de vergisting van glucose is minder gunstig dan de atoomeconomie van de productie van HMF uit glucose. Voor de productie van HMF is geen andere beginstof dan glucose nodig.$$, 'inline'),
  ('0b0de0b3-d274-4281-836a-c3f68c7d14a4', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$PEF is copolymeer van ethaan-1,2-diol en FDCA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context3.png$$,
   $$Zowel PET als PEF zijn polyesters. PEF is een copolymeer van ethaan-1,2-diol en FDCA (zie schema).$$, 'inline'),
  ('8d8779c9-77bf-4dd4-a5b6-f544b147f89a', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$sommige stoffen uit het schema als monomeer voor polyesters$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context4.png$$,
   $$Sommige andere stoffen uit het schema kunnen ook worden gebruikt als monomeren voor polyesters. De polymeren zijn dan meestal copolymeren van twee monomeren. Eén stof uit het schema kan echter zonder een ander monomeer als grondstof dienen voor een polyester.$$, 'inline'),
  ('b8258db1-e3d6-4f56-9836-4652aa6ac7d9', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$reactie 1 — HMF + methanol → MMF + H₂O; MMF is een ether$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context5.png$$,
   $$Avantium heeft een productieproces ontwikkeld waarbij FDCA met een hoog rendement geproduceerd kan worden uit HMF. De productie start met de reactie van HMF met methanol waarbij de stof MMF ontstaat. MMF is een ether. HMF + methanol → MMF + H₂O (reactie 1).$$, 'inline'),
  ('b421bfb7-6968-47fb-ac0a-b11c38900d76', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$reactie 2 — MMF + zuurstof → FDCA + methanol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context6.png$$,
   $$In het Avantium-proces wordt MMF vervolgens omgezet tot FDCA volgens reactie 2. MMF + zuurstof → FDCA + methanol (reactie 2).$$, 'inline'),
  ('175397ee-645b-49f2-b75a-bcc684ae4812', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$reactie 3 — MMF + zuurstof → FDCA + H₂O + CO₂ (oudere route)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context7.png$$,
   $$Een al langer bekend proces om MMF om te zetten tot FDCA is weergegeven in reactie 3. MMF + zuurstof → FDCA + H₂O + CO₂ (reactie 3).$$, 'inline'),
  ('b6795b94-f7af-49f9-bbe1-609418ed5632', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$rendement en duurzaamheid van het Avantium-proces (Groene Chemie)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context8.png$$,
   $$De productie van FDCA volgens reacties 1 en 2 heeft een hoger rendement dan volgens reacties 1 en 3. Ook is de productiemethode van Avantium duurzamer als je let op de uitgangspunten van de Groene Chemie. Een medewerker van Avantium schrijft een artikel voor een breed publiek. In het artikel verwerkt de medewerker twee argumenten op basis van uitgangspunten 1 en 2 van de Groene Chemie, zodat duidelijk wordt dat het productieproces van Avantium duurzamer is dan het oude proces.$$, 'inline'),
  ('b572d5d0-0d37-4bb7-a244-fd534570ed4f', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$CO₂-levenscyclus-uitstoot: drie punten in de berekening; PEF uit biomassa vs. PET uit aardolie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context9.png$$,
   $$Wetenschappers hebben met behulp van modellen de CO₂-uitstoot berekend tijdens de zogeheten levenscyclus van zowel PET als PEF. In de berekening van deze CO₂-levenscyclus-uitstoot wordt uitgegaan van de volgende punten: 1 de CO₂-uitstoot van het productieproces en het transport van stoffen; 2 PET en PEF worden even vaak gerecycled; 3 de CO₂-uitstoot van het verbranden van PET- en PEF-afval. De CO₂-uitstoot van de verbranding van PEF (punt 3) wordt buiten beschouwing gelaten als FDCA en ethaan-1,2-diol geheel uit biomassa worden gemaakt. De CO₂-uitstoot van de verbranding van PET wordt niet buiten beschouwing gelaten.$$, 'inline'),
  ('ec2acb05-0fe6-4de2-ac82-60f6c8480a19', 'bfd65c4a-d38d-44d6-b332-8a5929327548', $$berekende CO₂-levenscyclus-uitstoot: 0,8 ton (PEF) resp. 4,4 ton (PET) per ton polymeer$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-context10.png$$,
   $$De berekende waarde van de CO₂-uitstoot tijdens de levenscyclus van geheel uit biomassa gemaakt PEF is 0,8 ton CO₂ per ton polymeer. De berekende waarde van de CO₂-uitstoot tijdens de levenscyclus van PET is 4,4 ton CO₂ per ton polymeer.$$, 'inline'),
  ('25c3cf11-2110-4910-b97e-51c4f1a12ee2', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$figuur 1 — structuurkenmerken van fibroïne-vezels (gestapelde β-platen)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context1.png$$,
   $$Zijderupsen spinnen een cocon van zijdevezels waarin ze verpoppen. Deze vezels worden al eeuwen gebruikt om er kleding van te produceren. In de zijdevezels zijn twee soorten eiwitten aanwezig: sericine en fibroïne. De sericine vormt de buitenste laag van de vezels. Bij de productie van zijdegaren voor kleding wordt de sericine voor een groot deel verwijderd. De fibroïne komt voor in de vorm van vezels die niet alleen zacht maar ook sterk zijn. Figuur 1: in 1.1 zijn gebieden met gestapelde β-platen te zien, afgewisseld met ongeordende (slingerende) stukken eiwitketen; in 1.2 is schematisch met streepjes en bolletjes weergegeven hoe de eiwitketen heen en weer slingert in één β-plaat, met de restgroepen van Ala boven het vlak en de restgroepen van Gly onder het vlak.$$, 'inline'),
  ('571abb53-3f40-4def-b4fa-866231e08f8e', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$primaire structuur ~(Gly-Ala)n~; waterstofbruggen in het vlak van de β-plaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context2.png$$,
   $$In figuur 1.1 is te zien dat in fibroïne ongeordende stukken eiwitketen worden afgewisseld met sterk geordende gebieden. In de geordende gebieden zijn telkens ongeveer tien β-platen op elkaar gestapeld. De primaire structuur van de eiwitketen in een β-plaat in fibroïne kan vereenvoudigd worden weergegeven als ~(Gly-Ala)n~. In figuur 1.2 is schematisch met streepjes en bolletjes weergegeven dat de restgroepen van Ala zich steeds aan de ene zijde van een β-plaat bevinden, terwijl de restgroepen van Gly zich aan de andere zijde bevinden. Uit figuur 1.2 is op te maken dat de eiwitketen heen en weer slingert in een β-plaat. De C=O groepen en de N-H groepen van de aminozuureenheden in de eiwitketen liggen tegenover elkaar. Deze groepen vormen uitsluitend in het vlak van de β-plaat waterstofbruggen. Op de uitwerkbijlage is een fragment van een β-plaat onvolledig weergegeven; de eiwitketen in het fragment begint linksboven. Met een volle lijn zijn bindingen aangegeven die omhoog wijzen en met een stippellijn zijn bindingen aangegeven die naar beneden wijzen. Onder het fragment is schematisch ruimtelijk weergegeven hoe de eiwitketen op en neer gaat in een β-plaat.$$, 'inline'),
  ('57d2ee49-ede9-4146-8f7c-00b5a9aea6a3', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$elastische ongeordende gebieden vs. sterke vanderwaalsbinding tussen β-platen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context3.png$$,
   $$Binnen de fibroïne-vezels zijn de ongeordende stukken eiwitketen gemakkelijk te vervormen. Hiermee kunnen de elastische eigenschappen van zijde worden verklaard. De geordende gebieden vertonen daarentegen een grote weerstand tegen vervormen. Dit kan worden verklaard door de sterke vanderwaalsbinding die tussen de β-platen heerst.$$, 'inline'),
  ('a9c0d7b0-9f02-4494-927f-639823f90b91', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$twee tussenafstanden (0,35 nm en 0,57 nm) tussen gestapelde β-platen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context4.png$$,
   $$Uit metingen blijkt dat de β-platen in de geordende gebieden een regelmatige tussenafstand van afwisselend 0,35 nm en 0,57 nm vertonen. Dat er tussen de β-platen twee verschillende tussenafstanden bestaan, komt door de manier waarop de β-platen zijn gestapeld.$$, 'inline'),
  ('1aca1903-629b-4d27-903e-07d2992691bb', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$azoverbindingen (R-N=N-R, R = fenylgroep) als kleurstof voor zijderupsenvoedsel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context5.png$$,
   $$Zijde verven is erg milieubelastend, omdat veel water wordt verbruikt dat na gebruik vervuild is met resten van de kleurstoffen. Een groep Indiase onderzoekers heeft onderzocht of het mogelijk is de zijderupsen gekleurde zijde te laten produceren door hun voedsel te besprenkelen met kleurstoffen. De gekozen kleurstoffen behoren tot de zogeheten azoverbindingen. In azoverbindingen komt het structuurelement R-N=N-R voor. Hierbij staat R voor een fenylgroep. Azoverbindingen kunnen zowel in een cis- als in een trans-vorm voorkomen.$$, 'inline'),
  ('186bec99-bac9-42c6-bd29-593f8ff848c6', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$verdeling van kleurstof over hydrofiele sericine en hydrofobe fibroïne$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context6a.png$$,
   $$Als een rups de kleurstof heeft opgenomen, zal de kleurstof zich in het zijdespinsel verdelen over de relatief hydrofiele sericine en de hydrofobe fibroïne. Om vooraf te bepalen of een kleurstof overwegend in de sericine of in de fibroïne zal worden opgenomen, hebben de onderzoekers van een aantal kleurstoffen de verdelingscoëfficiënt bepaald in een tweelagensysteem van water en de hydrofobe vloeistof octaan-1-ol.$$, 'inline'),
  ('98d2d992-b66f-423a-ba34-b7d3f8a362d4', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$hypothese en definitie van de verdelingscoëfficiënt Kv$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context6b.png$$,
   $$Hierbij was de hypothese dat deze verdelingscoëfficiënt een relatie heeft met de mate van kleuring van beide vezelsoorten sericine en fibroïne. Deze verdelingscoëfficiënt Kv kan worden weergegeven als: Kv = [kleurstof]octaan-1-ol / [kleurstof]water.$$, 'inline'),
  ('fe706940-184c-4e99-8281-923e40c100d6', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$tabel — structuurformules en Kv-waarden van kleurstoffen D1 t/m D6$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context7.png$$,
   $$De resultaten van de onderzoekers zijn in onderstaande tabel samengevat. In de tabel staan de structuurformules van de deeltjes zoals die in een oplossing in water voorkomen. De onderzochte kleurstoffen zijn gerangschikt op toenemende Kv. Tabel: D1 (twee azogroepen, twee fenolgroepen met para-OH, twee sulfonaatgroepen (SO₃⁻) en een centrale C=C-dubbele binding tussen twee benzeenringen), Kv = 2·10⁻²; D2 (naftaleenring met OH-groep, één azogroep naar een fenylgroep, twee sulfonaatgroepen), Kv = 2·10⁻¹; D3 (naftaleenring met OH-groep, één azogroep naar een fenylgroep met één sulfonaatgroep), Kv = 2; D4 (naftaleenring met OH-groep, azogroep naar een tweede naftaleenring met OH- en sulfonaatgroep), Kv = 3; D5 (naftaleenring met OH-groep, azogroep naar een tweede naftaleenring met sulfonaatgroep, geen tweede OH), Kv = 4; D6 (naftaleenring met OH-groep, twee azogroepen na elkaar naar een fenyleenring en een eindstandige fenylgroep, geen sulfonaatgroep), Kv > 10².$$, 'inline'),
  ('546097ab-350d-4805-8cba-e652a6fc0f78', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$D3, D4 en D5 kleuren de cocons; D1, D2 en D6 geven geen kleuring$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-context8.png$$,
   $$Het blijkt dat de cocons gekleurd zijn als de stoffen D3, D4 en D5 aan het voedsel van de rupsen worden toegevoegd. De stoffen D1, D2 en D6 geven geheel geen kleuring. Op basis van de tabel en informatie uit deze opgave kan worden bepaald welke van de kleurstoffen D3, D4 of D5 het meest geschikt is om op deze manier zijdevezels voor textiel te kleuren.$$, 'inline'),
  ('5b3b17cb-a673-446a-b1d5-0e95bbce2839', '616dd7f7-5cd9-4989-98a1-6daeec6b6b1e', $$uitwerkbijlage vraag 9 — onvolledig fragment van een β-plaat (Gly-Ala-keten) en schematische stapeling$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-zijde-uitwerkbijlage-vraag9.png$$,
   $$uitwerkbijlage bij vraag 9: een onvolledig weergegeven fragment van een β-plaat, bestaande uit twee evenwijdige zigzag-eiwitketens (elk opgebouwd uit afwisselend N- en C-atomen), waarbij de eiwitketen linksboven begint; sommige koolstofatomen hebben nog geen restgroep (Ala/Gly) of waterstofbrug getekend. Onder het fragment is schematisch met vouwvlakken ('laag hoog laag hoog laag') weergegeven hoe de eiwitketen ruimtelijk op en neer gaat in een β-plaat.$$, 'uitwerkbijlage'),
  ('42f13660-d10b-47e3-ab90-dbab489590d7', '3ed28797-d260-4238-a4f0-f8d86e295662', $$fenolproductie via het cumeen-proces; blokschema op de uitwerkbijlage$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context1.png$$,
   $$Fenol (benzenol) is een belangrijke grondstof voor veel synthetische producten, waaronder geneesmiddelen en kunststoffen. Fenol wordt geproduceerd volgens het zogeheten cumeen-proces. Een vereenvoudigd blokschema van dit proces staat op de uitwerkbijlage. Uit het blokschema kan de totaalvergelijking voor de vorming van fenol volgens het cumeen-proces worden afgeleid.$$, 'inline'),
  ('a2776b76-5ea1-4586-afa8-94ce49be03b0', '3ed28797-d260-4238-a4f0-f8d86e295662', $$reactie 1 (propeen+benzeen→cumeen) en reactie in R2: cumeen + zuurstof → CHP$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context2.png$$,
   $$In reactor 1 (R1) reageert propeen volledig met benzeen. Daarbij ontstaat cumeen. In R2 reageert een deel van het gevormde cumeen met zuurstof tot cumeenhydroperoxide (CHP): H₃C-CH(CH₃)-C₆H₅ (cumeen) + O₂ → H₃C-C(CH₃)(C₆H₅)-O-O-H (CHP).$$, 'inline'),
  ('eceff632-7e65-4e73-8cc9-8ccdd3165624', '3ed28797-d260-4238-a4f0-f8d86e295662', $$S1: mengsel van 82,5 massa% CHP en 17,5 massa% cumeen; R3 vormt fenol en propanon (1:1), zwavelzuur als katalysator$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context3.png$$,
   $$In scheidingsruimte 1 (S1) wordt een groot deel van het overgebleven cumeen afgescheiden. Het mengsel dat overblijft, bevat 82,5 massa% CHP en 17,5 massa% cumeen. In R3 wordt CHP grotendeels omgezet tot fenol en propanon. Fenol en propanon ontstaan in de molverhouding 1:1. Hierbij wordt zwavelzuur als katalysator gebruikt. Omdat de reactie in R3 zeer exotherm is, is het belangrijk om de temperatuur in deze reactor nauwkeurig te regelen. Als de temperatuur te hoog oploopt, leidt dat namelijk tot veiligheidsrisico's. Tevens ontstaan dan ongewenste nevenproducten.$$, 'inline'),
  ('535d3240-a809-44c8-9cce-1c99b2118d20', '3ed28797-d260-4238-a4f0-f8d86e295662', $$R3 is een buisreactor; extra propanon wordt toegevoegd aan de instroom van R3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context4.png$$,
   $$Reactor 3 is een buisreactor. Door het grote oppervlak van de buis kan R3 goed worden gekoeld. Voordat het mengsel afkomstig uit S1 in R3 wordt gepompt, wordt nog extra propanon toegevoegd. Het toevoegen van propanon aan de instroom in R3 draagt bij aan een veilig proces in R3.$$, 'inline'),
  ('4a10ceb1-4943-4085-90c1-07c9be9318c1', '3ed28797-d260-4238-a4f0-f8d86e295662', $$gewenste molverhouding fenol:propanon in uitstroom R3 = 1,00:1,50; molaire massa's propanon en CHP$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context5.png$$,
   $$Aan de instroom in R3 wordt extra propanon toegevoegd, zodat in de uitstroom van R3 de molverhouding fenol:propanon gelijk is aan 1,00:1,50. De molaire massa van propanon is 58,1 g mol⁻¹ en die van CHP is 152 g mol⁻¹.$$, 'inline'),
  ('7bcc5398-75f7-41b2-ac38-9aeb36a533ac', '3ed28797-d260-4238-a4f0-f8d86e295662', $$CHP-controle via microreactor: temperatuurstijging 7,3 °C; definitie soortelijke warmte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context6.png$$,
   $$Het CHP-gehalte in de uitstroom van R3 wordt voortdurend gecontroleerd. Een gehalte hoger dan 2 massa% leidt namelijk tot explosiegevaar in de scheidingsruimten die erna komen. Deze controle gebeurt door een klein gedeelte van de uitstroom van R3 naar een microreactor te leiden. In de microreactor reageert het aanwezige CHP volgens dezelfde reactie als in R3, waardoor de temperatuur van de vloeistofstroom stijgt. Uit de temperatuurstijging van de vloeistofstroom kan het gehalte CHP in de uitstroom van R3 worden berekend. Op een gegeven moment wordt een temperatuurstijging van 7,3 °C gemeten. De soortelijke warmte van een stof kan worden gedefinieerd als het aantal joule dat nodig is om 1 g stof 1 K in temperatuur te laten stijgen.$$, 'inline'),
  ('c1945852-9bf8-4859-a7fc-848249729d6f', '3ed28797-d260-4238-a4f0-f8d86e295662', $$kookpunten van propanon, cumeen, CHP, fenol en zwavelzuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context7.png$$,
   $$In scheidingsruimten S2, S3 en S4 wordt het mengsel afkomstig uit R3 gescheiden door destillatie. De kookpunten (p = p0) van de stoffen bedragen: propanon (56 °C); cumeen (152 °C); CHP (153 °C); fenol (182 °C); zwavelzuur (330 °C).$$, 'inline'),
  ('bc50c68d-3317-4fcd-b812-7321cd0079cd', '3ed28797-d260-4238-a4f0-f8d86e295662', $$Mitsui-methode: propanon omzetten tot propeen via additie (R4) en eliminatie (R5)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-context8.png$$,
   $$Op de wereldmarkt stijgt de vraag naar fenol sneller dan de vraag naar propanon. Om te voorkomen dat propanon afval wordt, heeft het Japanse bedrijf Mitsui een methode ontwikkeld om de ontstane propanon om te zetten tot propeen. In een extra reactor (R4) verloopt de additie van waterstof aan de C=O groep van het propanon. In een volgende reactor (R5) ontstaan door een eliminatiereactie water en propeen uit de in R4 gevormde stof. Na een scheidingsstap (S5) wordt het gevormde propeen weer gebruikt in het cumeen-proces.$$, 'inline'),
  ('9e8ddb71-dd37-4db2-8a39-ba41613c81a4', '3ed28797-d260-4238-a4f0-f8d86e295662', $$uitwerkbijlage vraag 21 — blokschema van het cumeen-proces (R1-R3, S1-S4)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fenol-uitwerkbijlage-vraag21.png$$,
   $$uitwerkbijlage bij vraag 21: blokschema van het cumeen-proces. R1 zet propeen en benzeen om tot cumeen; cumeen gaat naar R2, waar het met zuurstof reageert tot een mengsel van CHP en cumeen; in S1 wordt cumeen afgescheiden en teruggevoerd naar R2; het overblijvende CHP/cumeen-mengsel gaat naar R3, waar met zwavelzuur als katalysator fenol en propanon ontstaan; de uitstroom van R3 gaat via S2 (waar zwavelzuur wordt afgescheiden) en S3 (waar propanon wordt afgescheiden en teruggevoerd naar R3) naar S4, waar tenslotte fenol en propanon als eindproducten worden afgescheiden. Voor de Mitsui-methode (vraag 21) moeten in dit schema nog de reactoren R4 en R5 en scheidingsstap S5 worden toegevoegd, die de afgescheiden propanon omzetten tot propeen, dat wordt teruggevoerd naar R1.$$, 'uitwerkbijlage'),
  ('f8e908e3-1f2b-49ba-8275-b2cd61a8eeb5', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$VRFB met vanadiumionen VO₂⁺, VO²⁺, V³⁺, V²⁺; opgelost zwavelzuur; membraan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-context1.png$$,
   $$Een Nederlandse melkveehouder voorziet sinds 2010 met zonnecellen in de eigen energiebehoefte. Voor de opslag van overdag teveel geproduceerde energie is op de boerderij een zogeheten Vanadium Redox Flow Battery (VRFB) geplaatst. In deze VRFB worden oplossingen met verschillende vanadiumionen vanuit twee opslagtanks door een aantal geschakelde elektrochemische cellen gepompt. Dit proces is in de figuur vereenvoudigd weergegeven met één elektrochemische cel. In deze opgave wordt de term vanadiumionen gebruikt voor (combinaties van) de deeltjes VO₂⁺, VO²⁺, V³⁺ en V²⁺. In beide oplossingen is verder alleen opgelost zwavelzuur aanwezig. Figuur: linker halfcel bevat VO²⁺/VO₂⁺ (met H⁺ en SO₄²⁻), rechter halfcel bevat V³⁺/V²⁺ (met H⁺ en SO₄²⁻), gescheiden door een membraan met + pool links en − pool rechts.$$, 'inline'),
  ('cdaa6a84-e83a-428f-9113-c765825c4eb9', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$beginsituatie: linkertank alleen VO²⁺, rechtertank alleen V³⁺; membraan laat vrijwel uitsluitend H⁺ door$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-context2.png$$,
   $$Wanneer de VRFB voor het eerst in gebruik wordt genomen, is van de genoemde vanadiumionen in de linker opslagtank alleen VO²⁺ aanwezig en in de rechter opslagtank alleen V³⁺. In deze situatie levert de VRFB geen stroom. Doordat in de VRFB selectieve membranen worden toegepast, worden tijdens het opladen en de stroomlevering vrijwel uitsluitend H⁺ ionen doorgelaten.$$, 'inline'),
  ('38e0ae36-a092-42f6-8344-ca95567ece40', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$CellCube FB 10-100: vermogen 10 kJ s⁻¹, opslagcapaciteit 100 kWh$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-context3.png$$,
   $$De VRFB van de fotonenboer is een CellCube type FB 10-100. Het typenummer geeft informatie over de twee belangrijkste kenmerken van de VRFB: het vermogen (de hoeveelheid energie die per seconde kan worden geleverd) bedraagt 10 kJ s⁻¹; de opslagcapaciteit (de maximale hoeveelheid elektrische energie die kan worden geleverd) bedraagt 100 kWh.$$, 'inline'),
  ('1a9a5ee5-05bb-4cd8-8db7-833ff7c68072', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$totaal rendement 67%; 1 mol elektronen levert 1,35·10⁵ J aan het lichtnet$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-context4.png$$,
   $$Het totale rendement van de omzetting van chemische energie in elektrische energie van deze VRFB bedraagt 67%. Bij stroomlevering geeft 1 mol elektronen 1,35·10⁵ J energie af aan het lichtnet.$$, 'inline'),
  ('f930b058-82e7-40e2-880c-8fa83d1e1f95', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$neerslag V₂O₅·3H₂O ontstaat uit VO₂⁺ en één andere stof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-context5.png$$,
   $$Uit onderzoek is gebleken dat onder bepaalde omstandigheden een neerslag van de vaste stof V₂O₅·3H₂O ontstaat in de linker opslagtank. Deze stof wordt gevormd uit VO₂⁺ ionen en één andere stof. Bij deze reactie ontstaat één ander soort deeltje.$$, 'inline'),
  ('259ddb70-68d9-47de-97d5-ab1e7ac15817', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$vijf mogelijke aanpassingen van de VRFB voor hogere opslagcapaciteit en stroomsterkte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-context6.png$$,
   $$Een andere boer wil een VRFB aanschaffen met een hogere opslagcapaciteit en een hogere maximale stroomsterkte dan de genoemde CellCube. In de tabel op de uitwerkbijlage staan vijf aanpassingen die de fabrikant kan doen om tegemoet te komen aan de eisen van deze boer. Uit de tabel valt onder andere op te maken dat een hogere concentratie vanadiumionen zorgt voor een toename van de opslagcapaciteit en de maximale stroomsterkte van de VRFB.$$, 'inline'),
  ('60e51c2c-b88e-4198-a743-28ddee27044d', '960ad8f2-1811-4204-90d9-9e97d5566fc5', $$uitwerkbijlage vraag 27 — tabel met vijf aanpassingen van de VRFB$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-fotonenboer-uitwerkbijlage-vraag27.png$$,
   $$uitwerkbijlage bij vraag 27: tabel met de kolom 'Aanpassing VRFB' (de concentratie vanadiumionen verhogen; meerdere elektrochemische cellen aansluiten op dezelfde tanks; de tanks vergroten; membranen gebruiken die de ionenstroom beter doorlaten; poreuze elektrodes gebruiken voor een groter contactoppervlak) en twee kolommen 'veroorzaakt een toename van de opslag-capaciteit (J)' resp. 'stroomsterkte (C s⁻¹)', waarbij bij de eerste aanpassing (concentratie verhogen) in beide kolommen al een kruisje (X) is ingevuld als voorbeeld.$$, 'uitwerkbijlage');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('ad8e0ba6-7d5c-420c-8f0a-23d442d153d2', 'bfd65c4a-d38d-44d6-b332-8a5929327548', 1,
