  ('db0c4890-96ef-4119-8e44-88c4c09785a7', 'bfd65c4a-d38d-44d6-b332-8a5929327548', 2,
   '[{"domain": "Technologie en duurzaamheid", "subdomain": "Groene chemie"}]'::jsonb,
   '["atoomeconomie berekenen", "glucose", "bio-ethanol", "HMF", "vergisting"]'::jsonb,
   $$Berekenen van de atoomeconomie van de productie van ethanol en van HMF uit glucose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-i-pef-fles-vraag2.png$$, $$Bereken de atoomeconomie van de productie van ethanol uit glucose en de atoomeconomie van de productie van HMF uit glucose. Gebruik Binas-tabel 37H of ScienceData-tabel 1.7.7.$$, array['f9d2d792-9231-4442-a471-08a5ee32e448', '571a1c46-4e4b-4c36-8e68-20a6b36c7cec']::uuid[]),
  ('ff910cbf-fbef-4eb1-bb9a-ec33630ae017', 'bfd65c4a-d38d-44d6-b332-8a5929327548', 3,
   '[{"domain": "Materie", "subdomain": "Deeltjesmodellen"}]'::jsonb,
   '["structuurformule", "copolymeer", "polyester", "condensatiepolymeer", "FDCA"]'::jsonb,
